// Noise and the hero skyline, as generated by the design.

// Seeded value noise (fractal Brownian motion): mist in the hero and the ridge strips.
let seed = 1234567;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
const P = Array.from({ length: 1024 }, rnd);
const n1 = (x: number) => { const i = Math.floor(x), f = x - i, t = f * f * (3 - 2 * f); return P[i & 1023] * (1 - t) + P[(i + 1) & 1023] * t; };
export const fbm = (x: number) => { let v = 0, a = 0.5, f = 1; for (let o = 0; o < 5; o++) { v += a * n1(x * f + o * 31.7); f *= 2.07; a *= 0.5; } return v / 0.97; };

// Real skyline from terrain data (Terrarium elevation tiles): Snezhanka and Golyam Perelik seen from Rozhen (41.6969N 24.7389E, 1746 m), bearing 228°, 54° wide, vertical ×3.5. Far → near.
// Each string is a profile: pairs of base-36 digits, elevation / 1000 as a fraction of the hero height.
const R = [
  '',
  '',
  '',
  '',
  '',
  '',
];

const dec = (str: string) => { const a = new Float32Array(str.length / 2); for (let i = 0; i < a.length; i++) a[i] = parseInt(str.slice(i * 2, i * 2 + 2), 36) / 1000; return a; };
const cols = ['#3a5652', '#2d4743', '#223834', '#192c29', '#132422', '#0d1a17'], par = [0.12, 0.25, 0.42, 0.62, 0.85, 1.1];

export interface Layer { c: string; d: number; p: Float32Array; m: number; front: boolean }
export const layers: Layer[] = R.map((str, i) => { const p = dec(str); let m = 0; for (let k = 60; k <= 300; k++) m += p[k]; return { c: cols[i], d: par[i], p, m: m / 241, front: i >= 4 }; });

export function ridge(p: Float32Array, xf: number) { const n = p.length - 1, u = Math.max(0, Math.min(n - 0.001, (xf + 0.25) / 1.5 * n)), i = Math.floor(u), f = u - i; return p[i] * (1 - f) + p[i + 1] * f; }
